{
  "questions": [
    {
      "stem": "環境保護の意識を高める（　）、学校でリサイクル活動を開始した。",
      "options": ["べく", "ために", "ように", "ため"],
      "answer_index": 0,
      "translation_zh": "为了提高环保意识，学校开始了回收活动。",
      "explanation_zh": "「〜べく」表目的，接辞书形，语体正式。「ために」「ように」接续或语感不符。","option_explanations_zh": [
        "正确：动词辞书形后接「べく」表示目的，符合书面语体。",
        "错误：「ために」虽表目的，但此处需体现更正式的书面风格。",
        "错误：「ように」多用于意志性弱的目的或变化结果，不自然。",
        "错误：「ため」后常接助词，直接接续动词辞书形不完整。"
      ]
    },
    {
      "stem": "この問題を解決す（　）、専門家チームを結成した。",
      "options": ["べく", "ために", "ように", "ため"],
      "answer_index": 0,
      "translation_zh": "为了解决这个问题，组建了专家团队。",
      "explanation_zh": "「する」接「べく」变为「すべく」表目的。「ために」「ように」接续或语体不当。","option_explanations_zh": [
        "正确：「する」的连用形「す」后接「べく」，构成正式书面表达。",
        "错误：「ために」虽可表目的，但无法体现原文所需的庄重语气。",
        "错误：「ように」多用于非意志性动作或结果，此处不适用。",
        "错误：「ため」需后续助词，单独接续动词辞书形不成立。"
      ]
    }
  ]
}
